	'sto_2' => 'Nach dem Umzug',
	'sto_2m' => 'Lebensumbruch und Einsamkeit · 8 Sitzungen',
	'sto_2p' => 'Eine Person fand nach einem Umzug und Monaten stiller Isolation wieder Halt und knüpfte neue Kontakte.',
	'sto_3' => 'Zwei Menschen, ein Küchentisch',
	'sto_3m' => 'Paare · 10 Sitzungen',
	'sto_3p' => 'Ein Paar lernte, seine sich wiederholenden Streitigkeiten zu verlangsamen und offen darüber zu sprechen, was eigentlich dahinterstand.',
